// @ts-nocheck
/* eslint-disable */
/**
 * Supporting-document form engine. GENERATED by tools/sync-supporting-doc-form.mjs from web/pages/sales_document_sub_{1…6}.xhtml + pages/inc/{sd_field_ro,sd_customer_field,save_confirm_dialog}.xhtml + resources/support/{crm_form.css,sd_customer_lazy.js} — do not edit; change the script and run `npm run supporting-doc-form:sync`.
 *
 * The scripts of the Java form, same behaviour line by line: the tabs and the toggles of the sections (the inline script), the confirmation of the save, the
 * read-only mode of the detail, the upload state, the file rows (view / download / description / delete with the SweetAlert confirm, the icon of the type of
 * the file) of save_confirm_dialog.xhtml.
 *
 * WHY it is imperative DOM code and not Angular components: the Java page is written that way; porting it 1:1 is what guarantees the screen and its states
 * are those of the production system. "@ts-nocheck": the source is ES5 written for a browser global scope; typing it would change it, not port it.
 *
 * What changed versus the Java files (all of it lives in tools/sync-supporting-doc-form.mjs):
 *   - the environment is injected (SupportingDocFormEnv): texts, SweetAlert, the mode (add / edit / detail) and the id of the document, navigation to the edit mode, the files of
 *     the browser (what /docattach served from the session), the address of a file, fetch (the BFF contract: /docattach);
 *   - location.search / location.href are env.actionType / env.docId / env.goEdit(); window.open is env.open(); swal(…) is env.swal(…);
 *   - the rows' handlers are static (docAttOpenUrl('view', null, null, this): the row knows its index and address);
 *   - document / jQuery listeners are added through listen() / the namespace .sdform and removed by destroy(); DOMContentLoaded handlers run through onReady().
 */

export interface SupportingDocFormEnv {
  /** commonBean.msg['key'] in the active language */
  t: (key: string) => string;
  /** SweetAlert (the library of the Java page) */
  swal: (options: Record<string, unknown>) => Promise<unknown>;
  /** the mode of the form (Java: ?action_type=) and the id of the document (?quotation_id=) */
  actionType: 'add' | 'edit' | 'detail';
  docId: () => string;
  /** the button "แก้ไขข้อมูล" of the detail: the same page in the edit mode */
  goEdit: () => void;
  /** the browser's own requests: /docattach (the files of the browser — DocAttachServlet), any other address goes to the network */
  fetch: (input: string, init?: RequestInit) => Promise<Response>;
  /** window.open(url, '_blank') — a /docattach address is the object URL of a file of the browser */
  open: (url: string) => void;
  /** the address of the file of row i (the backend's: through /docproxy in Java, the address itself here; '' for a file that is only in the browser) */
  fileUrl: (i: number) => string;
  /** commonBean.uploadMaxBytes / uploadMaxLabel */
  uploadMaxBytes: number;
  uploadMaxLabel: string;
  /** is the customer drop-down of the page there (add mode only): sdCustomerLazy.init needs it */
  hasCustomerSelect: () => boolean;
}

export function startSupportingDocForm(env: SupportingDocFormEnv): () => void {
  var destroyed = false;
  var disposers = [];
  var timers = [];
  var observers = [];
  function listen(target, type, fn, opts) {
    target.addEventListener(type, fn, opts);
    disposers.push(function () { target.removeEventListener(type, fn, opts); });
  }
  function tmo(fn, ms) { var h = setTimeout(function () { if (!destroyed) { fn(); } }, ms); timers.push(h); return h; }
  function track(o) { observers.push(o); return o; }
  /* document.readyState / DOMContentLoaded / load of the page the script was written for (see the generator) */
  var readyState = 'loading';
  var readyQueue = [];
  var loadQueue = [];
  function onReady(fn) { if (readyState === 'loading') { readyQueue.push(fn); } else { tmo(fn, 0); } }
  function onLoad(fn) { if (readyState !== 'complete') { loadQueue.push(fn); } else { tmo(fn, 0); } }
  function runQueue(queue, type) {
    queue.splice(0).forEach(function (fn) {
      try { fn.call(type === 'load' ? window : document, new Event(type)); } catch (e) { console.error(e); }
    });
  }

  /* Nothing that is still in flight when the screen is left may repaint it: after destroy() a request never settles. */
  var rawFetch = env.fetch;
  var never = function () { return new Promise(function () {}); };
  var guardResponse = function (r) {
    return {
      ok: r.ok, status: r.status, statusText: r.statusText, headers: r.headers, url: r.url,
      clone: function () { return guardResponse(r.clone()); },
      json: function () { return r.json().then(function (v) { return destroyed ? never() : v; }); },
      text: function () { return r.text().then(function (v) { return destroyed ? never() : v; }); },
      blob: function () { return r.blob().then(function (v) { return destroyed ? never() : v; }); },
      arrayBuffer: function () { return r.arrayBuffer().then(function (v) { return destroyed ? never() : v; }); }
    };
  };
  env = Object.assign({}, env, {
    fetch: function (a, b) {
      if (destroyed) { return never(); }
      return rawFetch(a, b).then(
        function (r) { return destroyed ? never() : guardResponse(r); },
        function (e) { return destroyed ? never() : Promise.reject(e); });
    }
  });

  /* ---- the inline script of the page ---- */
              window.ctActiveTab = 1;
              function ctShowTab(n) { window.ctActiveTab = n; ctApplyTab(); }
              function ctApplyTab() {
                  var n = window.ctActiveTab || 1;
                  var panes = document.querySelectorAll('.ct-pane');
                  Array.prototype.forEach.call(panes, function (p, i) { p.style.display = (i === (n - 1)) ? 'block' : 'none'; });
                  var tabs = document.querySelectorAll('.contract-tabbar .ct-tab');
                  Array.prototype.forEach.call(tabs, function (t) {
                      var tn = parseInt(t.getAttribute('data-tab'), 10);
                      if (tn === n) { t.classList.add('active'); } else { t.classList.remove('active'); }
                  });
              }
              function togglePanel(headerEl, panelId) {
                  var panel = document.getElementById(panelId);
                  if (!panel) { return; }
                  var icon = headerEl.querySelector('i');
                  var hidden = panel.style.display === 'none';
                  panel.style.display = hidden ? '' : 'none';
                  if (icon) { icon.classList.toggle('pi-chevron-up', hidden); icon.classList.toggle('pi-chevron-down', !hidden); }
              }
              if (window.jQuery) { jQuery(document).on('ajaxComplete.sdform', function () { ctApplyTab(); }); }
              onReady(ctApplyTab);

  /* ---- pages/inc/save_confirm_dialog.xhtml ---- */
          function sdOpenSaveConfirm() {
              var el = document.getElementById('sdSaveConfirmOverlay');
              if (!el) { return; }
              // โหมดแก้ไข (action_type=edit) → ข้อความ "อัปเดต"; โหมดเพิ่มใหม่ (add) → "บันทึก"
              var isEdit = env.actionType === 'edit';
              var t = document.getElementById('sdConfirmTitle');
              var d = document.getElementById('sdConfirmDesc');
              if (t) { t.textContent = isEdit ? env.t("label.sd.confirm_update_title") : env.t("label.contracts.confirm_save_title"); }
              if (d) { d.textContent = isEdit ? env.t("label.sd.confirm_update_desc") : env.t("label.sd.confirm_save_desc"); }
              el.classList.add('is-open');
          }
          function sdCloseSaveConfirm() {
              var el = document.getElementById('sdSaveConfirmOverlay');
              if (el) { el.classList.remove('is-open'); }
          }
          function sdConfirmOverlayClick(ev) {
              if (ev && ev.target && ev.target.id === 'sdSaveConfirmOverlay') { sdCloseSaveConfirm(); }
          }
          function sdConfirmSave() {
              sdCloseSaveConfirm();
              var btn = document.getElementById('quotationForm:realSaveBtn');
              if (btn) { btn.click(); }
          }
  
          /* ปุ่ม "แก้ไขข้อมูล" (โหมด detail) → เปิดหน้าเดิมเป็น edit mode (คง param อื่นครบ) เหมือนหน้า prospect */
          function sdGoEdit() {
              env.goEdit();
          }
  
          /* โหมด detail (กดไอคอน "ดู"/ลูกตา) = ดูอย่างเดียว แก้ไขข้อมูลใดๆ ไม่ได้ —
             disable ทุก input/textarea/select ที่ยัง editable ในฟอร์ม (บางช่องไม่ได้ใส่ disabled ไว้) */
          function sdApplyReadOnly() {
              if (env.actionType !== 'detail') { return; }
              var form = document.getElementById('quotationForm');
              if (!form) { return; }
              /* ★ 24/08: ติด class ให้ CSS ทำช่องที่ถูก disable ให้ดูเป็น "ตัวอักษรลอย" ไม่มีกรอบ
                 (ดูกฎ .sd-view-mode ด้านบน) — วิธีนี้ครอบคลุมฟอร์มใหญ่อย่าง sub_7 ที่มีช่องกว่า 270 ช่อง
                 โดยไม่ต้องไล่เปลี่ยนทีละ component */
              form.classList.add('sd-view-mode');
              var els = form.querySelectorAll('input, textarea, select');
              Array.prototype.forEach.call(els, function (el) {
                  var t = (el.type || '').toLowerCase();
                  if (t === 'hidden' || t === 'button' || t === 'submit' || t === 'file') { return; }
                  el.disabled = true;
                  el.readOnly = true;
              });
          }
          onReady(sdApplyReadOnly);
          if (window.jQuery) { jQuery(document).on('ajaxComplete.sdform', function () { sdApplyReadOnly(); }); }
  
          /* ===== 24/08: สถานะ "กำลังอัปโหลด" ของแท็บเอกสาร =====
             p:fileUpload (advanced + auto + sequential) ยิง 1 request ต่อ 1 ไฟล์
             ⇒ oncomplete ถูกเรียกเท่าจำนวนไฟล์ แต่ onstart เรียกครั้งเดียวตอนเริ่มคิว
             ถ้าโชว์/ซ่อนตาม onstart-oncomplete ตรง ๆ แถบจะหายตั้งแต่ไฟล์แรกเสร็จทั้งที่ยังอัปไม่ครบ
             จึงนับจำนวนไฟล์ที่ผู้ใช้เลือก (event change ของ input file) แล้วนับถอยหลังทุกครั้งที่ไฟล์จบ */
          var _sdUpLeft = 0;
          var _sdUpWatchdog = null;
  
          function sdUploadRender() {
              var on = _sdUpLeft > 0;
              var box = document.getElementById('sdUploadLoading');
              var wrap = document.querySelector('.sd-doc-wrap');
              var cnt = document.getElementById('sdUploadCount');
              if (box) { box.classList.toggle('is-on', on); }
              if (wrap) { wrap.classList.toggle('is-uploading', on); }
              if (cnt) { cnt.textContent = (on && _sdUpLeft > 1) ? ('(' + _sdUpLeft + ')') : ''; }
          }
  
          /* n = จำนวนไฟล์ที่ยังค้างอยู่ ; ตั้งทุกครั้งพร้อม re-arm watchdog
             watchdog กันแถบค้างถาวรเมื่อ callback ของ PrimeFaces ไม่ถูกเรียก (เน็ตหลุดกลางคัน ฯลฯ) */
          function sdUploadSet(n) {
              _sdUpLeft = (n > 0) ? n : 0;
              sdUploadRender();
              if (_sdUpWatchdog) { clearTimeout(_sdUpWatchdog); _sdUpWatchdog = null; }
              if (_sdUpLeft > 0) {
                  _sdUpWatchdog = tmo(function () { sdUploadSet(0); }, 180000);
              }
          }
          /* onstart: กันเหนียวกรณีที่ไม่ได้ผ่าน event change (จึงยังไม่รู้จำนวนไฟล์) — นับเป็น 1 ไปก่อน
             อย่างน้อยผู้ใช้ยังเห็นว่าระบบกำลังทำงาน ไม่ใช่หน้าจอนิ่งเฉย */
          function sdUploadStart() { if (_sdUpLeft <= 0) { sdUploadSet(1); } }
          /* 1 ไฟล์จบ (สำเร็จ/พลาด validate/ถูกยกเลิก) → ลดตัวนับ ครบแล้วแถบหายเอง */
          function sdUploadDone() { sdUploadSet(_sdUpLeft - 1); }
  
          /* เพดานขนาดไฟล์แนบ (ไบต์) — ค่าเดียวกับ sizeLimit ของ p:fileUpload
             มาจาก triplesale.upload.max.bytes ใน config.properties แหล่งเดียว (ดูที่มาของตัวเลขในไฟล์นั้น) */
          var SD_UPLOAD_MAX_BYTES = env.uploadMaxBytes;
          var SD_UPLOAD_MAX_LABEL = env.uploadMaxLabel;
          var SD_UPLOAD_ALLOW_TYPES = 'PDF, DOC(X), XLS(X), PPT(X), CSV, TXT, JPG, JPEG, PNG, GIF, BMP, WEBP, HEIC, TIF(F), ZIP, RAR, 7Z';
  
          function sdBytesText(bytes) {
              var mb = bytes / 1048576;
              return (mb >= 10 ? Math.round(mb) : Math.round(mb * 10) / 10) + ' MB';
          }
  
          /* ★ 24/08: ไฟล์ถูกปฏิเสธตอน validate ฝั่ง client
             เดิม PrimeFaces เงียบสนิท (ไฟล์ไม่โผล่ในรายการ ไม่มีข้อความใด ๆ) ผู้ใช้จึงเห็นเป็น "อัปโหลดไม่ได้ ไม่รู้สาเหตุ"
             — ยืนยันจาก log จริง: FileUploadUtils.isValidFileName ปฏิเสธ .csv เพราะไม่อยู่ใน regex
  
             ★★ 24/08 (รอบ 2): มี 2 สาเหตุแล้วหลังใส่ sizeLimit ⇒ ต้องแยกข้อความ ไม่งั้นไฟล์ใหญ่เกิน
                จะได้ข้อความ "นามสกุลที่รับได้..." ซึ่งไม่เกี่ยวกันเลย ผู้ใช้ยิ่งงง
                PrimeFaces เรียก callback นี้พร้อม object {summary, filename, filesize} (ยืนยันจาก
                fileupload.js ของ PF 14.0.7) — ตัดสินจาก filesize เองแทนที่จะอ่านข้อความใน summary
                เพราะ summary เป็นข้อความตามภาษาของธีม เปลี่ยนได้ ไม่ควรเอามาเป็นเงื่อนไข */
          function sdUploadRejected(err) {
              sdUploadDone();
              var size = (err && typeof err.filesize === 'number') ? err.filesize : 0;
              var name = (err && err.filename) ? err.filename : '';
              if (size > SD_UPLOAD_MAX_BYTES) {
                  env.swal({
                      title: env.t("label.sd.upload_too_big_title"),
                      text: (name ? name + '\n' : '')
                          + env.t("label.sd.upload_too_big_msg")
                                .replace('{0}', sdBytesText(size))
                                .replace('{1}', SD_UPLOAD_MAX_LABEL),
                      icon: 'warning'
                  });
                  return;
              }
              env.swal({
                  title: env.t("label.ld2.upload_failed"),
                  text: SD_UPLOAD_ALLOW_TYPES,
                  icon: 'warning'
              });
          }
  
          /* ผู้ใช้เลือกไฟล์จากปุ่มอัปโหลด → รู้จำนวนไฟล์ล่วงหน้า (auto=true อัปทันที ไม่ต้องกดยืนยันซ้ำ)
             ใช้ capture phase ให้ทำงานก่อน handler ของ PrimeFaces เอง */
          listen(document, 'change', function (ev) {
              var t = ev.target;
              if (!t || String(t.type).toLowerCase() !== 'file') { return; }
              if (!t.closest || !t.closest('.sd-doc-uploadbar')) { return; }
              var n = (t.files && t.files.length) ? t.files.length : 0;
              if (n > 0) { sdUploadSet(n); }
          }, true);
  
          /* ★ 24/08: ลากไฟล์มาวาง — ไม่เกิด event change ที่ input (PrimeFaces หยิบไฟล์จาก dataTransfer ตรง ๆ)
             ถ้าไม่นับตรงนี้ แถบ "กำลังอัปโหลด" จะรู้จำนวนไฟล์แค่ 1 (จาก onstart) แล้วหายตั้งแต่ไฟล์แรกเสร็จ */
          listen(document, 'drop', function (ev) {
              var t = ev.target;
              if (!t || !t.closest || !t.closest('.sd-doc-wrap')) { return; }
              var dt = ev.dataTransfer;
              var n = (dt && dt.files && dt.files.length) ? dt.files.length : 0;
              if (n > 0) { sdUploadSet(n); }
          }, true);
  
          /* ★ 24/08: ยืนยันลบไฟล์แนบด้วย swal แทน window.confirm() ของเบราว์เซอร์
             ใช้ชุดเดียวกับหน้าลูกค้าเป้าหมาย/contracts/RV (21/08 ทีมตั้งใจทำให้ popup ทั้งระบบไปทางเดียวกัน):
             icon=warning + dangerMode + ปุ่ม [ยกเลิก][ลบ]
  
             ★★ โครงสร้างปุ่มลบ = 2 ชิ้น (ดู markup ในหน้า sales_document_sub_*)
               (1) ไอคอนถังขยะที่ผู้ใช้เห็น = <i> ธรรมดา → เรียกฟังก์ชันนี้
               (2) p:commandLink ตัวจริง (.sd-doc-del-real) ซ่อนไว้ในแถวเดียวกัน ไม่มี onclick ของเราเลย
                   ⇒ onclick ที่ PrimeFaces สร้างให้เป็น PrimeFaces.ab(...) ล้วน ๆ สั่ง .click() แล้วยิง ajax แน่นอน
             เดิมผูก onclick ยืนยันไว้บนตัว commandLink แล้วอาศัย "คลิกซ้ำรอบสองให้คืน true" ซึ่งพึ่ง contract
             ภายในของ PrimeFaces.bcn (ค่า this ที่ส่งเข้า callback / ลำดับการเรียก / การกลืน exception)
             มากเกินไป — เวลาพังจะพังแบบเงียบสนิท debug ไม่ได้เลย */
          function sdAskDeleteFile(iconEl) {
              var row = (iconEl && iconEl.closest) ? iconEl.closest('.sd-doc-row') : null;
              var real = row ? row.querySelector('.sd-doc-del-real') : null;
              if (!real) {
                  env.swal({ title: env.t("label.sd.delete_file_fail"), icon: 'error' });
                  return;
              }
              env.swal({
                  title: env.t("label.sd.confirm_delete_file"),
                  icon: 'warning',
                  buttons: [env.t("chat.cancel"), env.t("label.cmd.delete_tip")],
                  dangerMode: true
              }).then(function (willDelete) {
                  if (willDelete) { real.click(); }
              });
          }
  
          // ===== ไฟล์แนบ (แท็บเอกสาร) — ดู/ดาวน์โหลด/แก้ไขรายละเอียด ผ่าน servlet /docattach =====
          function docAttDocId() {
              return env.docId();
          }
          /* URL ของไฟล์ที่ยังอยู่แค่ session store (ยังไม่ได้ persist ขึ้น backend) — เสิร์ฟผ่าน servlet /docattach */
          function docAttServletUrl(action, i) {
              var id = docAttDocId();
              if (!id) { return ''; }
              return '/docattach?action=' + action + '&docId=' + encodeURIComponent(id) + '&i=' + i;
          }
          /* ดู/ดาวน์โหลดไฟล์แนบ
             url มีค่า = ไฟล์จริงจาก backend (ผ่าน /docproxy) ; ว่าง = ไฟล์เพิ่งอัป ยังอยู่ใน session store
             ★ 24/08: เดิมดาวน์โหลดด้วย <a download> / window.location.href ตรง ๆ — ถ้าปลายทาง 404,
             โดน redirect ไปหน้า login, หรือ docproxy ปฏิเสธ host ผู้ใช้จะเห็นแค่ "กดแล้วไม่มีอะไรเกิดขึ้น"
             เปลี่ยนเป็น fetch ก่อนแล้วตรวจผลจริง: ได้ไฟล์ → ดาวน์โหลดจาก blob (ตั้งชื่อไฟล์ได้ด้วย),
             ไม่ได้ → ขึ้น popup บอกสาเหตุ ไม่เงียบอีกต่อไป */
          /* ★ 24/08: ปุ่มลบไฟล์เป็น ajax — ถ้า JSF ตก validation/convert ที่ช่องไหนสักช่องในฟอร์ม
             phase INVOKE_APPLICATION จะถูกข้าม ⇒ action ลบไฟล์ไม่ถูกเรียก และ "เงียบสนิท"
             (ยิ่งตอนนี้เอา p:growl ออกแล้วยิ่งไม่มีอะไรบอกผู้ใช้เลย) — ดักที่ oncomplete แล้วบอกให้ชัด
             คู่กับการใส่ process="@this" ที่ตัวปุ่ม (ลบไฟล์ไม่ต้องใช้ค่าจากช่องอื่นเลย จึงไม่ควรประมวลผลทั้งฟอร์ม) */
          function sdAfterDeleteFile(xhr, status, args) {
              if (args && args.validationFailed) {
                  env.swal({ title: env.t("label.sd.delete_file_fail"), icon: 'error' });
              }
          }
  
          /* ชื่อไฟล์ของแถวที่ถูกคลิก — อ่านจาก DOM ไม่ส่งเป็นสตริงใน onclick
             (ชื่อไฟล์ที่มีเครื่องหมาย ' จะทำ JS ใน attribute พังทั้งแถว) */
          function sdRowFilename(el) {
              try {
                  var row = (el && el.closest) ? el.closest('.sd-doc-row') : null;
                  if (!row) { return ''; }
                  var ic = row.querySelector('.sd-doc-ic');
                  var dn = ic ? ic.getAttribute('data-name') : '';
                  if (dn) { return dn; }
                  var nm = row.querySelector('.sd-doc-name');
                  return nm ? nm.textContent.trim() : '';
              } catch (e) { return ''; }
          }
          function docAttOpenUrl(action, url, i, srcEl) {
              if (url === null || i === null) {
                  var rowEl = srcEl.closest('.sd-doc-row');
                  i = Array.prototype.indexOf.call(rowEl.parentNode.querySelectorAll('.sd-doc-row'), rowEl);
                  url = env.fileUrl(i);
              }
              var filename = sdRowFilename(srcEl);
              var target = (url && url.length) ? url : docAttServletUrl(action, i);
              if (!target) {
                  env.swal({ title: env.t("label.ld2.upload_failed"), text: env.t("label.sd.save_before_view"), icon: 'warning' });
                  return;
              }
              if (action !== 'download') { env.open(target); return; }
              env.fetch(target, { credentials: 'same-origin' })
                  .then(function (r) {
                      if (!r.ok) {
                          var why = r.headers.get('X-DocProxy-Reason');   /* รหัสสาเหตุจาก DocProxy (BLOCKED_HOST / UPSTREAM_404 / NETWORK ...) */
                          throw new Error('HTTP ' + r.status + (why ? ' ' + why : ''));
                      }
                      var ct = r.headers.get('content-type') || '';
                      /* ได้ html กลับมา = โดนเด้งไปหน้า login / error page ไม่ใช่ไฟล์ */
                      if (ct.indexOf('text/html') >= 0) { throw new Error('HTML (session/redirect)'); }
                      return r.blob();
                  })
                  .then(function (b) {
                      var href = URL.createObjectURL(b);
                      var a = document.createElement('a');
                      a.href = href;
                      a.download = filename || 'download';
                      document.body.appendChild(a);
                      a.click();
                      if (a.parentNode) { a.parentNode.removeChild(a); }
                      tmo(function () { URL.revokeObjectURL(href); }, 1000);
                  })
                  .catch(function (err) {
                      env.swal({
                          title: env.t("label.ld2.error_occurred"),
                          text: String((err && err.message) ? err.message : err),
                          icon: 'error'
                      });
                  });
          }
          function docAttEditDesc(i) {
              var id = docAttDocId();
              if (!id) { env.swal({ title: 'ข้อความแจ้งเตือน!', text: env.t("label.sd.save_before_edit"), icon: 'warning', timer: 3000, buttons: false }); return; }
              var el = document.querySelector('.att-desc[data-i="' + i + '"]');
              var cur = el ? el.textContent.trim() : '';
              if (cur === env.t("label.sd.no_detail")) { cur = ''; }
              // ★ 21/08: เปลี่ยนจาก prompt() เบราว์เซอร์ล้วน เป็น swal แบบมีช่องกรอก (content: input)
              //   ให้หน้าตาไปในแนวเดียวกับ popup อื่นทั้งระบบ
              var inputEl = document.createElement('input');
              inputEl.className = 'swal-content__input';
              inputEl.value = cur;
              inputEl.style.cssText = 'width:100%;padding:8px 10px;border:1px solid #D1D5DB;border-radius:6px;font-size:14px;box-sizing:border-box;';
              env.swal({
                  title: env.t("label.sd.file_detail"),
                  content: inputEl,
                  buttons: [env.t("chat.cancel"), env.t("label.cmd.ok_btn")]
              }).then(function (confirmed) {
                  if (!confirmed) { return; }
                  var v = inputEl.value;
                  env.fetch('/docattach?action=describe&docId=' + encodeURIComponent(id) + '&i=' + i, {
                      method: 'POST',
                      headers: { 'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8' },
                      body: 'text=' + encodeURIComponent(v)
                  }).then(function (r) { return r.json(); })
                    .then(function (res) {
                        if (res && res.status === 200) {
                            if (el) {
                                el.textContent = v ? v : env.t("label.sd.no_detail");
                                el.style.fontStyle = v ? 'normal' : 'italic';
                                el.style.color = v ? '#555' : '#999';
                            }
                        } else { env.swal({ title: 'บันทึกไม่สำเร็จ!', text: env.t("label.sd.save_detail_fail"), icon: 'error' }); }
                    }).catch(function () { env.swal({ title: 'บันทึกไม่สำเร็จ!', text: env.t("label.sd.save_detail_fail"), icon: 'error' }); });
              });
          }
  
          /* ไอคอนตามชนิดไฟล์ (นามสกุล): word/excel/pdf/zip/รูปภาพ = สัญลักษณ์ของมัน, อื่น ๆ = รูปเอกสารทั่วไป
             ชุดเดียวกับหน้าลูกค้าเป้าหมาย (contracts) — ใช้ FontAwesome (โหลดจาก template) */
          function sdDocIconFor(name) {
              var ext = String(name || '').toLowerCase().split('.').pop();
              var map = {
                  pdf:  ['fa-file-pdf', '#CD1515'],
                  doc:  ['fa-file-word', '#2B579A'], docx: ['fa-file-word', '#2B579A'],
                  xls:  ['fa-file-excel', '#217346'], xlsx: ['fa-file-excel', '#217346'], csv: ['fa-file-excel', '#217346'],
                  ppt:  ['fa-file-powerpoint', '#C43E1C'], pptx: ['fa-file-powerpoint', '#C43E1C'],
                  zip:  ['fa-file-zipper', '#B45309'], rar: ['fa-file-zipper', '#B45309'], '7z': ['fa-file-zipper', '#B45309'],
                  png:  ['fa-file-image', '#0D9488'], jpg: ['fa-file-image', '#0D9488'], jpeg: ['fa-file-image', '#0D9488'],
                  gif:  ['fa-file-image', '#0D9488'], webp: ['fa-file-image', '#0D9488'], bmp: ['fa-file-image', '#0D9488'], svg: ['fa-file-image', '#0D9488']
              };
              return map[ext] || ['fa-file-lines', '#35236A'];
          }
          function sdApplyDocIcons() {
              var els = document.querySelectorAll('.sd-doc-ic');
              Array.prototype.forEach.call(els, function (ic) {
                  var info = sdDocIconFor(ic.getAttribute('data-name'));
                  ic.className = 'fas ' + info[0] + ' sd-doc-ic';
                  ic.style.color = info[1];
              });
          }
          onReady(sdApplyDocIcons);
          /* re-apply หลัง PrimeFaces ajax (อัปโหลด/ลบ = update @form → row render ใหม่) */
          if (window.jQuery) { jQuery(document).on('ajaxComplete.sdform', function () { sdApplyDocIcons(); }); }

  /* ---- pages/inc/sd_customer_field.xhtml: <script>sdCustomerLazy.init('sdCustomerWv');</script> (sd_customer_lazy.js is loaded by the host) ---- */
  onReady(function () { if (window.sdCustomerLazy && env.hasCustomerSelect()) { sdCustomerLazy.init('sdCustomerWv'); } });

  /* the entry points of the inline handlers and of the window.* functions */
  window.sdOpenSaveConfirm = sdOpenSaveConfirm;
  window.sdCloseSaveConfirm = sdCloseSaveConfirm;
  window.sdConfirmOverlayClick = sdConfirmOverlayClick;
  window.sdConfirmSave = sdConfirmSave;
  window.sdGoEdit = sdGoEdit;
  window.sdAskDeleteFile = sdAskDeleteFile;
  window.sdAfterDeleteFile = sdAfterDeleteFile;
  window.docAttOpenUrl = docAttOpenUrl;
  window.docAttEditDesc = docAttEditDesc;
  window.ctShowTab = ctShowTab;
  window.togglePanel = togglePanel;
  window.sdUploadStart = sdUploadStart;
  window.sdUploadDone = sdUploadDone;
  window.sdUploadRejected = sdUploadRejected;
  var EXPORTED = ["sdOpenSaveConfirm","sdCloseSaveConfirm","sdConfirmOverlayClick","sdConfirmSave","sdGoEdit","sdAskDeleteFile","sdAfterDeleteFile","docAttOpenUrl","docAttEditDesc","ctShowTab","togglePanel","sdUploadStart","sdUploadDone","sdUploadRejected","ctActiveTab"];

  /* "the document has been parsed": DOMContentLoaded handlers in the order they were registered, then "load" */
  readyState = 'interactive';
  runQueue(readyQueue, 'DOMContentLoaded');
  readyState = 'complete';
  tmo(function () { runQueue(loadQueue, 'load'); }, 0);

  return function destroy() {
    destroyed = true;
    disposers.splice(0).forEach(function (d) { d(); });
    timers.splice(0).forEach(function (h) { clearTimeout(h); });
    observers.splice(0).forEach(function (o) { o.disconnect(); });
    if (window.jQuery) { jQuery(document).off('.sdform'); }
    EXPORTED.forEach(function (n) { try { delete window[n]; } catch (e) { window[n] = undefined; } });
  };
}
